// Package postcard implements the schema-less Rust `postcard` v1 wire
// format: 8-bit integers as raw bytes, wider integers as LEB128 varints
// (zig-zag for signed), floats as little-endian fixed width, bytes and
// strings length-prefixed, options as a 0/1 tag, and enums as a varint
// variant index followed by fields.
//
// Murmur persists Spool payloads, checkpoints, and replication messages in
// this format, so this package must stay byte-compatible with the Rust
// `postcard` crate. Test vectors in postcard_test.go were generated by the
// real Rust implementation (see /tmp/vecgen.rs, kept out of the repo).
//
// Only the standard library is used.
package postcard

import (
	"errors"
	"math"
	"unicode/utf8"
)

var (
	// ErrTruncated reports input that ends mid-value.
	ErrTruncated = errors.New("postcard: truncated input")
	// ErrOverflow reports a varint that exceeds its target width.
	ErrOverflow = errors.New("postcard: varint overflow")
	// ErrValue reports a syntactically valid but illegal value (for
	// example a bool tag other than 0 or 1, or invalid UTF-8).
	ErrValue = errors.New("postcard: invalid value")
	// ErrTrailing reports unconsumed bytes after a top-level value.
	ErrTrailing = errors.New("postcard: trailing bytes")
)

// Encoder accumulates one postcard value. The zero value is ready to use.
type Encoder struct {
	buf []byte
}

// NewEncoder returns an Encoder with the given capacity hint.
func NewEncoder(capHint int) *Encoder {
	return &Encoder{buf: make([]byte, 0, capHint)}
}

// Bytes returns the encoded value. The slice stays owned by the Encoder.
func (e *Encoder) Bytes() []byte { return e.buf }

// Reset clears the buffer for reuse.
func (e *Encoder) Reset() { e.buf = e.buf[:0] }

func (e *Encoder) uvarint(v uint64) {
	for v >= 0x80 {
		e.buf = append(e.buf, byte(v)|0x80)
		v >>= 7
	}
	e.buf = append(e.buf, byte(v))
}

// U8 appends a raw byte.
func (e *Encoder) U8(v uint8) { e.buf = append(e.buf, v) }

// I8 appends a raw byte.
func (e *Encoder) I8(v int8) { e.buf = append(e.buf, byte(v)) }

// U16 appends an unsigned varint.
func (e *Encoder) U16(v uint16) { e.uvarint(uint64(v)) }

// U32 appends an unsigned varint.
func (e *Encoder) U32(v uint32) { e.uvarint(uint64(v)) }

// U64 appends an unsigned varint.
func (e *Encoder) U64(v uint64) { e.uvarint(v) }

// I16 appends a zig-zag varint.
func (e *Encoder) I16(v int16) {
	x := int32(v)
	e.uvarint(uint64(uint32(x<<1) ^ uint32(x>>31)))
}

// I32 appends a zig-zag varint.
func (e *Encoder) I32(v int32) {
	e.uvarint(uint64(uint32(v<<1) ^ uint32(v>>31)))
}

// I64 appends a zig-zag varint.
func (e *Encoder) I64(v int64) {
	e.uvarint(uint64(uint64(v<<1) ^ uint64(v>>63)))
}

// Bool appends a 0/1 tag.
func (e *Encoder) Bool(v bool) {
	if v {
		e.buf = append(e.buf, 1)
	} else {
		e.buf = append(e.buf, 0)
	}
}

// F32 appends 4 little-endian bytes.
func (e *Encoder) F32(v float32) {
	b := math.Float32bits(v)
	e.buf = append(e.buf, byte(b), byte(b>>8), byte(b>>16), byte(b>>24))
}

// F64 appends 8 little-endian bytes.
func (e *Encoder) F64(v float64) {
	b := math.Float64bits(v)
	e.buf = append(e.buf,
		byte(b), byte(b>>8), byte(b>>16), byte(b>>24),
		byte(b>>32), byte(b>>40), byte(b>>48), byte(b>>56))
}

// Raw appends bytes without a length prefix (fixed-size arrays).
func (e *Encoder) Raw(b []byte) { e.buf = append(e.buf, b...) }

// Len appends a varint length prefix for a slice, map, string, or bytes.
func (e *Encoder) Len(n int) { e.uvarint(uint64(n)) }

// ByteString appends a length-prefixed byte string.
func (e *Encoder) ByteString(b []byte) {
	e.uvarint(uint64(len(b)))
	e.buf = append(e.buf, b...)
}

// String appends a length-prefixed string.
func (e *Encoder) String(s string) {
	e.uvarint(uint64(len(s)))
	e.buf = append(e.buf, s...)
}

// Discriminant appends an enum variant index as a varint u32.
func (e *Encoder) Discriminant(v uint32) { e.uvarint(uint64(v)) }

// None appends an option-absent tag.
func (e *Encoder) None() { e.buf = append(e.buf, 0) }

// Some appends an option-present tag; the caller then encodes the value.
func (e *Encoder) Some() { e.buf = append(e.buf, 1) }

// Decoder reads one postcard value from a byte slice. It records the
// first error and yields zero values afterwards; callers check Err at
// the end (and End to reject trailing bytes).
type Decoder struct {
	buf []byte
	off int
	err error
}

// NewDecoder reads from b without copying it.
func NewDecoder(b []byte) *Decoder { return &Decoder{buf: b} }

// Err returns the first decode error, if any.
func (d *Decoder) Err() error { return d.err }

// Offset returns the number of bytes consumed so far.
func (d *Decoder) Offset() int { return d.off }

// Remaining returns the number of unread bytes.
func (d *Decoder) Remaining() int {
	if d.err != nil {
		return 0
	}
	return len(d.buf) - d.off
}

// End reports Err if decoding failed, or ErrTrailing if bytes remain.
func (d *Decoder) End() error {
	if d.err != nil {
		return d.err
	}
	if d.off != len(d.buf) {
		return ErrTrailing
	}
	return nil
}

func (d *Decoder) fail(err error) {
	if d.err == nil {
		d.err = err
	}
}

// Fail records a semantic decode error (for example a bad enum
// discriminant) and yields zero values afterwards, like Err/End.
func (d *Decoder) Fail(err error) { d.fail(err) }

func (d *Decoder) byte() byte {
	if d.err != nil {
		return 0
	}
	if d.off >= len(d.buf) {
		d.fail(ErrTruncated)
		return 0
	}
	b := d.buf[d.off]
	d.off++
	return b
}

func (d *Decoder) uvarint() uint64 {
	if d.err != nil {
		return 0
	}
	var v uint64
	for i := 0; i < 10; i++ {
		if d.off >= len(d.buf) {
			d.fail(ErrTruncated)
			return 0
		}
		b := d.buf[d.off]
		d.off++
		if i == 9 && b > 1 {
			// The tenth byte may only carry bit 63, without
			// continuation.
			d.fail(ErrOverflow)
			return 0
		}
		v |= uint64(b&0x7F) << (7 * uint(i))
		if b&0x80 == 0 {
			return v
		}
	}
	d.fail(ErrOverflow)
	return 0
}

// U8 reads a raw byte.
func (d *Decoder) U8() uint8 { return d.byte() }

// I8 reads a raw byte.
func (d *Decoder) I8() int8 { return int8(d.byte()) }

// U16 reads an unsigned varint.
func (d *Decoder) U16() uint16 {
	v := d.uvarint()
	if d.err == nil && v > math.MaxUint16 {
		d.fail(ErrOverflow)
	}
	return uint16(v)
}

// U32 reads an unsigned varint.
func (d *Decoder) U32() uint32 {
	v := d.uvarint()
	if d.err == nil && v > math.MaxUint32 {
		d.fail(ErrOverflow)
	}
	return uint32(v)
}

// U64 reads an unsigned varint.
func (d *Decoder) U64() uint64 { return d.uvarint() }

// Discriminant reads an enum variant index.
func (d *Decoder) Discriminant() uint32 { return d.U32() }

func zigzag64(n uint64) int64 {
	return int64(n>>1) ^ -int64(n&1)
}

// I16 reads a zig-zag varint.
func (d *Decoder) I16() int16 {
	n := d.uvarint()
	if d.err != nil {
		return 0
	}
	v := zigzag64(n)
	if v > math.MaxInt16 || v < math.MinInt16 {
		d.fail(ErrOverflow)
	}
	return int16(v)
}

// I32 reads a zig-zag varint.
func (d *Decoder) I32() int32 {
	n := d.uvarint()
	if d.err != nil {
		return 0
	}
	v := zigzag64(n)
	if v > math.MaxInt32 || v < math.MinInt32 {
		d.fail(ErrOverflow)
	}
	return int32(v)
}

// I64 reads a zig-zag varint.
func (d *Decoder) I64() int64 {
	n := d.uvarint()
	if d.err != nil {
		return 0
	}
	return zigzag64(n)
}

// Bool reads a 0/1 tag.
func (d *Decoder) Bool() bool {
	b := d.byte()
	if d.err != nil {
		return false
	}
	if b > 1 {
		d.fail(ErrValue)
		return false
	}
	return b == 1
}

// Present reads an option tag: true when a value follows.
func (d *Decoder) Present() bool { return d.Bool() }

// F32 reads 4 little-endian bytes.
func (d *Decoder) F32() float32 {
	b := d.fixed(4)
	if b == nil {
		return 0
	}
	return math.Float32frombits(uint32(b[0]) | uint32(b[1])<<8 | uint32(b[2])<<16 | uint32(b[3])<<24)
}

// F64 reads 8 little-endian bytes.
func (d *Decoder) F64() float64 {
	b := d.fixed(8)
	if b == nil {
		return 0
	}
	return math.Float64frombits(
		uint64(b[0]) | uint64(b[1])<<8 | uint64(b[2])<<16 | uint64(b[3])<<24 |
			uint64(b[4])<<32 | uint64(b[5])<<40 | uint64(b[6])<<48 | uint64(b[7])<<56)
}

func (d *Decoder) fixed(n int) []byte {
	if d.err != nil {
		return nil
	}
	if uint64(len(d.buf)-d.off) < uint64(n) {
		d.fail(ErrTruncated)
		return nil
	}
	b := d.buf[d.off : d.off+n]
	d.off += n
	return b
}

// Raw reads n bytes without a length prefix. The slice aliases the
// input; copy it before retaining.
func (d *Decoder) Raw(n int) []byte { return d.fixed(n) }

// Len reads a varint length prefix.
func (d *Decoder) Len() int {
	v := d.uvarint()
	if d.err != nil {
		return 0
	}
	if v > uint64(math.MaxInt) {
		d.fail(ErrOverflow)
		return 0
	}
	return int(v)
}

// Bytes reads a length-prefixed byte string. The slice aliases the
// input; copy it before retaining.
func (d *Decoder) Bytes() []byte {
	n := d.Len()
	if d.err != nil {
		return nil
	}
	return d.fixed(n)
}

// String reads a length-prefixed string, rejecting invalid UTF-8.
func (d *Decoder) String() string {
	b := d.Bytes()
	if d.err != nil {
		return ""
	}
	if !utf8.Valid(b) {
		d.fail(ErrValue)
		return ""
	}
	return string(b)
}
